package br.radaraero.widget;
import android.app.job.*;import android.content.*;import org.json.*;import java.net.*;import java.util.*;
public class RefreshJob extends JobService {
 volatile Thread task;static void schedule(Context c){JobScheduler s=(JobScheduler)c.getSystemService(JOB_SCHEDULER_SERVICE);s.schedule(new JobInfo.Builder(4201,new ComponentName(c,RefreshJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(0).build());}
 @Override public boolean onStartJob(JobParameters params){task=new Thread(()->{try{android.content.SharedPreferences prefs=getSharedPreferences("radar",0);String config=prefs.getString("point",null);if(config==null){RadarWidget.drawAll(this,"Configure o ponto");return;}JSONObject p=new JSONObject(config);double lat=p.getDouble("lat"),lon=p.getDouble("lon");int radius=p.getInt("radiusKm");HttpURLConnection conn=(HttpURLConnection)new URL("https://api.adsb.lol/v2/lat/"+lat+"/lon/"+lon+"/dist/"+(int)Math.ceil(radius/1.852+1)).openConnection();conn.setConnectTimeout(5000);conn.setReadTimeout(5000);JSONObject raw;try(java.io.InputStream in=conn.getInputStream()){byte[] bytes=ConfigureActivity.readLimited(in,2000000);if(bytes.length>2000000)throw new Exception();raw=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));}finally{conn.disconnect();}JSONArray ac=raw.getJSONArray("ac");ArrayList<JSONObject> found=new ArrayList<>();long at=System.currentTimeMillis();double source=raw.optDouble("now",at/1000.0);if(source>1e12)source/=1000;for(int i=0;i<ac.length();i++){JSONObject a=ac.getJSONObject(i);if(a.opt("lat")==null||a.isNull("lat")||a.isNull("lon")||"ground".equals(a.optString("alt_baro")))continue;double age=Math.max(0,at/1000.0-source+a.optDouble("seen_pos",Double.POSITIVE_INFINITY));double d=distance(lat,lon,a.optDouble("lat",Double.NaN),a.optDouble("lon",Double.NaN));if(!Double.isFinite(d)||d>radius||age>120)continue;String call=a.optString("flight","").trim();if(!call.matches("[A-Za-z0-9][A-Za-z0-9-]{1,11}"))call=a.optString("r",a.optString("hex","Aeronave"));String company=call.startsWith("TAM")?"LATAM":call.startsWith("AZU")?"Azul":call.startsWith("GLO")?"GOL":"";String alt=a.isNull("alt_baro")?"altitude —":a.optString("alt_baro")+" pés";JSONObject row=new JSONObject();row.put("displayCall",call);row.put("company",company);row.put("model",a.optString("t","modelo —"));row.put("altitude",alt);row.put("positionAt",at-(long)(age*1000));row.put("route","Consultando rota…");row.put("distance",d);row.put("callsign",a.optString("flight","").trim());row.put("label",String.format(Locale.forLanguageTag("pt-BR"),"%s %s · %.1f km\n%s · %s · posição %.0f s",company,call,d,a.optString("t","modelo —"),alt,age));found.add(row);}found.sort(Comparator.comparingDouble(a->a.optDouble("distance")));JSONArray rows=new JSONArray();for(int i=0;i<Math.min(3,found.size());i++)rows.put(found.get(i));JSONObject snap=new JSONObject();snap.put("at",at);snap.put("rows",rows);if(config.equals(prefs.getString("point",null))&&!Thread.currentThread().isInterrupted()){prefs.edit().putString("snapshot",snap.toString()).apply();RadarWidget.drawAll(this,"");}for(int i=0;i<rows.length();i++){if(Thread.currentThread().isInterrupted())break;JSONObject row=rows.getJSONObject(i);String route=FlightRoutes.lookup(row.optString("callsign"));row.put("route",route);row.put("label",row.getString("label")+"\n"+route);}if(config.equals(prefs.getString("point",null))&&!Thread.currentThread().isInterrupted()){prefs.edit().putString("snapshot",snap.toString()).apply();RadarWidget.drawAll(this,"");}}
 catch(Exception e){RadarWidget.drawAll(this,"Sem atualização · toque em Atualizar");}finally{jobFinished(params,false);}});task.start();return true;}
 @Override public boolean onStopJob(JobParameters p){if(task!=null)task.interrupt();return true;}
 static double distance(double lat,double lon,double a,double b){double r=Math.PI/180,h=Math.pow(Math.sin((a-lat)*r/2),2)+Math.cos(lat*r)*Math.cos(a*r)*Math.pow(Math.sin((b-lon)*r/2),2);return 6371*2*Math.asin(Math.sqrt(Math.min(1,h)));}
}
